/** Small byte-level utilities shared by zip.ts and tar.ts. Not part of the public API. */

const encoder = new TextEncoder()
const decoder = new TextDecoder()

export function utf8Encode(value: string): Uint8Array {
  return encoder.encode(value)
}

export function utf8Decode(bytes: Uint8Array): string {
  return decoder.decode(bytes)
}

/**
 * A plain `ArrayBuffer` copy of `bytes`. Needed because `Uint8Array.prototype.slice`/`subarray`
 * type as `Uint8Array<ArrayBufferLike>` (which may be a `SharedArrayBuffer`), while DOM APIs like
 * `Blob`'s constructor require an `ArrayBuffer`-backed view.
 */
export function toArrayBuffer(bytes: Uint8Array): ArrayBuffer {
  return bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer
}

export function concatBytes(parts: Uint8Array[]): Uint8Array {
  const total = parts.reduce((sum, part) => sum + part.byteLength, 0)
  const out = new Uint8Array(total)
  let offset = 0
  for (const part of parts) {
    out.set(part, offset)
    offset += part.byteLength
  }
  return out
}
