import { decodeResponse, encodeFileFrame, encodeRawFrame, isTeFrame, parseDeviceInfo, parseIdentityDeviceId, DEFAULT_DEVICE_ID } from './frame.js'
import type { DeviceInfo } from './frame.js'
import { decodeEvent } from './events.js'
import type { FileEvent } from './types.js'
import type { MidiTransport } from './transport.js'
import type { FileResponse } from './types.js'

export type SessionState = 'disconnected' | 'ready' | 'transferring'
export type { DeviceInfo } from './frame.js'

export class Ep133Error extends Error {
  constructor(message: string, readonly status?: number) {
    super(message)
    this.name = 'Ep133Error'
  }
}

/**
 * `respCmd` is set on every waiter created by request()/requestDuringTransfer()
 * (never by the handshake, which uses a different match predicate). It backs the
 * single-outstanding-per-cmd invariant — see Ep133Session class doc.
 */
type Waiter = {
  match: (b: Uint8Array) => boolean
  resolve: (b: Uint8Array) => void
  reject: (e: Error) => void
  respCmd?: number
}

/**
 * Measured on the real device: it echoes the request's `seq` byte on 218/218
 * solicited responses (including all 140 download frames), and echoes
 * `cmd - 0x40`. Correlation is by (cmd, seq) TOGETHER.
 *
 * A timed-out request's late reply carries a dead seq and matches no live waiter
 * — unless the shared seq counter wraps an exact multiple of 128 between the two
 * sends, which fireAndForget can cause. That is unreachable today because:
 * (1) request()/requestDuringTransfer() enforce at most one outstanding awaited
 * request per respCmd, and (2) a timeout aborts the enclosing operation rather
 * than being caught and retried on the same respCmd. A future op that catches a
 * timeout and retries on the same respCmd while fireAndForget advances the
 * counter in between would reopen this — such an op must reset or skip the seq.
 *
 * The one place seq is NOT correlation: the 1083 fire-and-forget upload chunk
 * ACKs, which cycle the 7-bit seq counter many times over. Those are never
 * awaited, so they never touch this matching logic at all.
 */
export class Ep133Session {
  #state: SessionState = 'disconnected'
  private seq = 0
  private waiters: Waiter[] = []
  private eventListeners: Array<(e: FileEvent) => void> = []
  /** TE SysEx identity_code: 0x33 (EP-133) or 0x3c (EP-40 firmware). */
  private deviceId = DEFAULT_DEVICE_ID

  constructor(private readonly transport: MidiTransport) {
    transport.onMessage((b) => this.dispatch(b))
  }

  get state(): SessionState {
    return this.#state
  }

  get identityCode(): number {
    return this.deviceId
  }

  private dispatch(b: Uint8Array): void {
    for (let i = this.waiters.length - 1; i >= 0; i--) {
      const w = this.waiters[i]!
      if (w.match(b)) { this.waiters.splice(i, 1); w.resolve(b); return }
    }
    // Unmatched frames are chunk ACKs, dead requests' late replies, or unsolicited
    // device events. The ACKs and corpses are drained on purpose — see Global
    // Constraints. The events are real: our handshake's FILE_INIT sets flags=SUBSCRIBE,
    // so the device announces every add, delete, move and metadata change, including
    // the ones the user makes on the front panel.
    if (this.eventListeners.length > 0) {
      const event = decodeEvent(b)
      if (event) for (const cb of this.eventListeners) cb(event)
    }
  }

  private nextSeq(): number {
    const s = this.seq
    this.seq = (this.seq + 1) & 0x7f
    return s
  }

  /**
   * `respCmd`, when provided, marks this wait as owned by a real device request
   * for the single-outstanding-per-cmd invariant (assertNoOutstanding). It plays
   * no role in matching a reply — that's entirely the caller-supplied `match`
   * predicate now, keyed on (cmd, seq). The handshake's identity/init waits omit
   * it since they're not subject to that invariant.
   */
  private await_(match: (b: Uint8Array) => boolean, timeoutMs: number, label: string, respCmd?: number): Promise<Uint8Array> {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        const i = this.waiters.indexOf(w)
        if (i >= 0) {
          this.waiters.splice(i, 1)
          reject(new Ep133Error(`timeout waiting for ${label}`))
        }
      }, timeoutMs)
      const w: Waiter = {
        match,
        respCmd,
        resolve: (b) => { clearTimeout(timer); resolve(b) },
        reject: (e) => { clearTimeout(timer); reject(e) },
      }
      this.waiters.push(w)
    })
  }

  async connect(): Promise<DeviceInfo> {
    if (this.#state !== 'disconnected') {
      throw new Ep133Error(`connect() requires state=disconnected (state=${this.#state}); use reinit() instead`)
    }
    const info = await this.handshake()
    this.#state = 'ready'
    return info
  }

  /** Mandatory after any completed get()/put(). The device otherwise drops the next command. */
  async reinit(): Promise<void> {
    await this.handshake()
    this.#state = 'ready'
  }

  private async handshake(): Promise<DeviceInfo> {
    // Waiters are registered before send() in every step, same as request() —
    // a transport that replies synchronously inside send() (see
    // ImmediateTransport in the tests) would otherwise deliver its reply to
    // nobody.
    const identity = this.await_((b) => b[0] === 0xf0 && b[1] === 0x7e, 2000, 'identity')
    this.transport.send(Uint8Array.of(0xf0, 0x7e, 0x7f, 0x06, 0x01, 0xf7))
    const idFrame = await identity.catch(() => undefined)
    if (idFrame) {
      const id = parseIdentityDeviceId(idFrame)
      if (id !== null) this.deviceId = id
    }

    const init1 = this.await_((b) => isTeFrame(b) && b[6] === 0x21, 2000, 'init1')
    this.transport.send(encodeRawFrame(0x61, 0x17, [0x01], this.deviceId))
    const r1 = await init1

    const init2 = this.await_((b) => isTeFrame(b) && b[6] === 0x21, 2000, 'init2')
    this.transport.send(encodeRawFrame(0x61, 0x18, [0x05, 0x00, 0x01, 0x01, 0x00, 0x40, 0x00, 0x00], this.deviceId))
    await init2

    return parseDeviceInfo(r1)
  }

  enterTransfer(): void {
    if (this.#state !== 'ready') throw new Ep133Error(`enterTransfer() requires state=ready (state=${this.#state})`)
    this.#state = 'transferring'
  }

  private assertNoOutstanding(respCmd: number): void {
    if (this.waiters.some((w) => w.respCmd === respCmd)) {
      throw new Ep133Error(`two concurrent requests await cmd 0x${respCmd.toString(16)}`)
    }
  }

  /**
   * Computes the seq about to be sent, registers a waiter matching (respCmd,
   * seq) TOGETHER, and only then sends. The register-before-send ordering is
   * load-bearing (see 'a reply delivered synchronously inside send()' test) —
   * do not reorder this.
   */
  private async awaitReply(cmd: number, payload: number[], respCmd: number, timeoutMs: number, checkStatus: boolean): Promise<FileResponse> {
    const seq = this.nextSeq()
    const p = this.await_(
      (b) => isTeFrame(b) && b[6] === respCmd && b[7] === seq,
      timeoutMs,
      `cmd 0x${respCmd.toString(16)} seq 0x${seq.toString(16)}`,
      respCmd,
    )
    this.transport.send(encodeFileFrame(cmd, seq, payload, this.deviceId))
    const raw = await p
    const res = decodeResponse(raw)
    if (!res) throw new Ep133Error('undecodable response')
    if (checkStatus && res.status !== 0) throw new Ep133Error(`device returned status=0x${res.status.toString(16)}`, res.status)
    return res
  }

  /**
   * Correlates on (respCmd, seq) — see the class doc. Not declared `async` on
   * purpose: the state check must surface as a promise rejection (callers await
   * it like any other failure), while the concurrent-request check is a
   * caller-misuse bug and must throw synchronously, before a second waiter for
   * the same respCmd is ever registered.
   */
  request(
    cmd: number,
    payload: number[],
    respCmd: number,
    timeoutMs = 2000,
    opts: { checkStatus?: boolean } = {},
  ): Promise<FileResponse> {
    if (this.#state !== 'ready') return Promise.reject(new Ep133Error(`session not ready (state=${this.#state})`))
    this.assertNoOutstanding(respCmd)
    return this.awaitReply(cmd, payload, respCmd, timeoutMs, opts.checkStatus ?? true)
  }

  /** Pipelined chunk sends. No correlation, no await. */
  fireAndForget(cmd: number, payload: number[]): void {
    this.transport.send(encodeFileFrame(cmd, this.nextSeq(), payload, this.deviceId))
  }

  /**
   * Same as request() but permitted while transferring. Used for chunk-loop
   * internals. `checkStatus` defaults to true, matching request(); download chunk
   * pages will opt out later by passing `{ checkStatus: false }` because the
   * device reports a non-fatal non-zero status mid-download that the chunk loop
   * itself must interpret, not treat as a hard failure.
   */
  requestDuringTransfer(
    cmd: number,
    payload: number[],
    respCmd: number,
    timeoutMs = 2500,
    opts: { checkStatus?: boolean } = {},
  ): Promise<FileResponse> {
    this.assertNoOutstanding(respCmd)
    return this.awaitReply(cmd, payload, respCmd, timeoutMs, opts.checkStatus ?? true)
  }

  /**
   * Listen for unsolicited device events. The handshake's FILE_INIT sets flags=SUBSCRIBE,
   * so the device announces every file add, delete, move and metadata change — including
   * ones the user makes on the front panel.
   */
  onEvent(cb: (e: FileEvent) => void): () => void {
    this.eventListeners.push(cb)
    return () => { this.eventListeners = this.eventListeners.filter((f) => f !== cb) }
  }

  close(): void {
    this.transport.close()
    for (const w of this.waiters) w.reject(new Ep133Error('session closed'))
    this.waiters = []
    this.#state = 'disconnected'
  }
}
