/** Malformed or unsupported ZIP data. */
export class ZipFormatError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'ZipFormatError'
  }
}

/** Malformed tar data. */
export class TarFormatError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'TarFormatError'
  }
}

/** A pad record buffer that isn't exactly 26 bytes, or other pad-record decode failure. */
export class PadRecordError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'PadRecordError'
  }
}

/** Malformed RIFF/WAVE data. */
export class WavFormatError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'WavFormatError'
  }
}

/** Malformed .pak/.ppak structure, or a write that would violate a device-safety invariant. */
export class PakFormatError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'PakFormatError'
  }
}
