import { Ep133Error, type Ep133Session } from '../session.js'
import { be16, be32 } from '../wire.js'
import { SOUNDS_NODE, UPLOAD_CHUNK, type SlotMeta } from '../types.js'
import { getNodeMetadata } from './metadata.js'
import { crc32 } from '../crc32.js'

/** setNodeMetadata's own write-side limit; the inlined upload-init metadata write must obey it too. */
const MAX_METADATA_BYTES = 320

/**
 * `idx` is a BE16 chunk index (0..0xFFFF). The largest legal sample is 40s
 * mono = 3.75 MB; at UPLOAD_CHUNK (433) bytes/chunk that's ~9100 chunks, well
 * inside the limit. Bounding the loop here makes the margin an explicit,
 * checked invariant instead of an incidental one — see downloadSlot's
 * MAX_DOWNLOAD_PAGES for the same pattern on the read side.
 */
const MAX_CHUNKS = 0xffff

export function* chunkOffsets(total: number): Generator<number> {
  for (let off = 0; off < total; off += UPLOAD_CHUNK) yield off
}

/**
 * Deliberately omits sound.bpm (0.0 is rejected on write) and, for untrimmed
 * sources, the loop fields (writing them destroys the -1/-2 sentinels forever).
 */
export function buildUploadMetadata(opts: {
  channels: number
  samplerate: number
  trimmed: boolean
  frames: number
}): Record<string, unknown> {
  const meta: Record<string, unknown> = {
    'sound.playmode': 'oneshot',
    'sound.rootnote': 60,
    'sound.pitch': 0,
    'sound.pan': 0,
    'sound.amplitude': 100,
    'envelope.attack': 0,
    'envelope.release': 255,
    'time.mode': 'off',
    channels: opts.channels,
    samplerate: opts.samplerate,
  }
  if (opts.trimmed && opts.frames > 0) {
    meta['sound.loopstart'] = 0
    meta['sound.loopend'] = opts.frames - 1
  }
  return meta
}

export async function uploadSlot(
  session: Ep133Session,
  slot: number,
  pcm: Uint8Array,
  name: string,
  meta: Record<string, unknown>,
  onProgress?: (done: number, total: number, phase: 'queuing' | 'committed') => void,
): Promise<void> {
  if (pcm.length === 0) {
    throw new Ep133Error(`uploadSlot: pcm is empty, nothing to upload for slot ${slot}`)
  }

  const chunkCount = Math.ceil(pcm.length / UPLOAD_CHUNK)
  if (chunkCount > MAX_CHUNKS) {
    throw new Ep133Error(
      `uploadSlot: slot ${slot} needs ${chunkCount} chunks of ${UPLOAD_CHUNK} bytes, ` +
        `exceeding the BE16 chunk-index limit of ${MAX_CHUNKS} (${pcm.length} bytes total; ` +
        `the largest legal sample, 40s mono, is 3.75 MB)`,
    )
  }

  const nameBytes = [...new TextEncoder().encode(name.slice(0, 20))]
  const jsonBytes = [...new TextEncoder().encode(JSON.stringify(meta))]

  // Same 320-byte device page limit setNodeMetadata guards — this write is inlined
  // into the upload-init frame instead of going through setNodeMetadata, so it must
  // enforce the limit itself rather than silently truncating on the wire.
  if (jsonBytes.length > MAX_METADATA_BYTES) {
    throw new Ep133Error(
      `uploadSlot: metadata is ${jsonBytes.length} bytes, exceeds the ${MAX_METADATA_BYTES}-byte device page limit`,
    )
  }

  // NOTE ON `checkStatus: false` THROUGHOUT THE UPLOAD PATH.
  // krate/PROTOCOL.md:152 — "Device responds with an ACK ... It does not return a standard
  // status=0x00 response, so clients should only check that an ACK was received." krate's
  // _send_and_wait_msg never inspects status on this path either. Asserting status here
  // would throw against real hardware. Upload integrity is instead established afterwards
  // by reading the slot's metadata back and comparing its `crc` field against crc32(pcm)
  // (see the end of this function) — a real end-to-end check, unlike a status byte the
  // device does not populate on this path.
  await session.requestDuringTransfer(
    0x7e,
    [0x02, 0x00, 0x05, ...be16(slot), ...be16(SOUNDS_NODE), ...be32(pcm.length), ...nameBytes, 0x00, ...jsonBytes],
    0x3e,
    5000,
    { checkStatus: false },
  )

  session.enterTransfer()

  // Mandatory try/finally: a barrier timeout, a rejected metadata write, or any other
  // failure between enterTransfer() and the drain barrier below must not leave the
  // session stuck 'transferring' — every later session.request() would then reject
  // with "session not ready" and nothing would recover it. Mirrors downloadSlot's
  // try/catch/finally exactly: reinit() always runs, and a reinit() failure must not
  // mask an in-flight error from the try block above it.
  let pending: unknown
  try {
    // Pipelined: fire every chunk, await none. Their ACKs are drained by the session.
    let idx = 0
    for (const off of chunkOffsets(pcm.length)) {
      const slice = pcm.subarray(off, Math.min(off + UPLOAD_CHUNK, pcm.length))
      session.fireAndForget(0x7e, [0x02, 0x01, ...be16(idx), ...slice])
      idx++
      // `queuing`, not real progress: MIDIOutput.send() only queues the frame for the
      // OS/driver to transmit — it does not confirm delivery, let alone that the device
      // has ingested the audio. This loop can reach 100% in milliseconds while the
      // device is still chewing through seconds of queued MIDI. The 'committed' phase
      // below, fired once after the drain barrier resolves, is the only point at which
      // "done" is actually true.
      onProgress?.(Math.min(off + UPLOAD_CHUNK, pcm.length), pcm.length, 'queuing')
    }

    // DO NOT await the end sentinel's ACK, and do not await the verify ACK.
    //
    // Measured on hardware 2026-07-09: uploading 1083 chunks produced only 1012 `0x3E`
    // responses — the device does not ACK every chunk. Those ACKs share the sentinel's cmd
    // AND collide with its 7-bit seq (1083 chunks cycle all 128 values ~8 times), and they
    // arrive first. Any waiter for `0x3E` here resolves on a chunk ACK, not on the sentinel,
    // and the upload appears to finish while the device is still ingesting audio.
    //
    // MIDI delivery is strictly ordered, so the barrier we CAN trust is the first response to
    // a command whose response-cmd the chunk ACKs cannot impersonate. `METADATA SET` answers
    // with `0x2A`. It cannot arrive until the device has consumed every frame queued before it.
    session.fireAndForget(0x7e, [0x02, 0x01, ...be16(idx)]) // end sentinel
    session.fireAndForget(0x7e, [0x0b, ...be16(slot)]) // verify

    // This await IS the drain barrier. Give it the full upload budget.
    await session.requestDuringTransfer(
      0x6a,
      [0x07, 0x01, ...be16(slot), ...new TextEncoder().encode(JSON.stringify(meta))],
      0x2a,
      180_000,
    )

    onProgress?.(pcm.length, pcm.length, 'committed')
  } catch (err) {
    pending = err
    throw err
  } finally {
    try {
      await session.reinit()
    } catch (reinitErr) {
      if (pending === undefined) throw reinitErr
    }
  }

  // The CRC read-back happens AFTER the finally above, so the session is already back
  // to 'ready' by the time we get here — a CRC mismatch throws with the device in a
  // clean state, not stuck mid-transfer.
  //
  // This is the real verification: the device computes `crc` (standard CRC-32, zlib/PKZIP
  // variant) over the slot's raw PCM bytes — confirmed against four real slots on the
  // attached device (see crc32.ts). Comparing it against crc32(pcm) catches a truncated
  // upload (e.g. dropped tail chunks) that channels/samplerate — both of which the client
  // itself wrote into this same metadata blob seconds earlier — can never catch, because
  // they round-trip regardless of how much PCM actually reached the device.
  const after = await getNodeMetadata<SlotMeta>(session, slot)
  const expectedCrc = crc32(pcm)
  if (after.crc !== expectedCrc) {
    throw new Ep133Error(
      `upload verification failed for slot ${slot}: device reports crc=${after.crc}, ` +
        `expected crc=${expectedCrc} (crc32 of ${pcm.length} PCM bytes)`,
    )
  }

  // Cheap secondary check, kept from before the CRC fix: catches the case where the
  // device accepted a different sample-rate/channel interpretation than intended even
  // though the bytes themselves matched (crc32 has no notion of format).
  if (after.channels !== meta['channels'] || after.samplerate !== meta['samplerate']) {
    throw new Ep133Error(
      `upload verification failed for slot ${slot}: device reports ` +
        `${after.channels}ch @ ${after.samplerate}Hz, expected ${meta['channels']}ch @ ${meta['samplerate']}Hz`,
    )
  }
}
