/** TE 8-to-7 transport encoding. Groups of 7; flags byte first. */
export function pack7(data: Uint8Array): Uint8Array {
  const groups = Math.ceil(data.length / 7)
  const out = new Uint8Array(groups + data.length)
  let o = 0
  for (let i = 0; i < data.length; i += 7) {
    const end = Math.min(i + 7, data.length)
    const flagsAt = o++
    let flags = 0
    for (let j = i; j < end; j++) {
      const b = data[j]!
      if (b & 0x80) flags |= 1 << (j - i)
      out[o++] = b & 0x7f
    }
    out[flagsAt] = flags
  }
  return out
}

export function unpack7(data: Uint8Array): Uint8Array {
  const out: number[] = []
  let i = 0
  while (i < data.length) {
    const flags = data[i++]!
    for (let bit = 0; bit < 7 && i < data.length; bit++, i++) {
      out.push((data[i]! & 0x7f) | (((flags >> bit) & 1) << 7))
    }
  }
  return Uint8Array.from(out)
}
