const POLY = 0xedb88320

let table: Uint32Array | undefined

function buildTable(): Uint32Array {
  const t = new Uint32Array(256)
  for (let n = 0; n < 256; n++) {
    let c = n
    for (let k = 0; k < 8; k++) {
      c = c & 1 ? POLY ^ (c >>> 1) : c >>> 1
    }
    t[n] = c >>> 0
  }
  return t
}

/**
 * Standard CRC-32 — the zlib/PKZIP variant: polynomial 0xEDB88320 (reflected),
 * init 0xFFFFFFFF, final XOR 0xFFFFFFFF. Matches Python's `zlib.crc32` bit for
 * bit, and matches the EP-133 K.O. II's own slot-metadata `crc` field: verified
 * against four real slots on the attached device (2026-07-09) —
 *   slot 1 (micro kick):  device crc 2874448156 == zlib.crc32(pcm)
 *   slot 3 (nt kick b):   device crc  317284627 == zlib.crc32(pcm)
 *   slot 100 (nt snare):  device crc  784862880 == zlib.crc32(pcm)
 *   slot 400 (nt bass):   device crc 1844073479 == zlib.crc32(pcm)
 * See `ops/upload.ts` for how this is used to verify an upload landed intact.
 */
export function crc32(data: Uint8Array): number {
  const t = (table ??= buildTable())
  let crc = 0xffffffff
  for (let i = 0; i < data.length; i++) {
    crc = t[(crc ^ data[i]!) & 0xff]! ^ (crc >>> 8)
  }
  return (crc ^ 0xffffffff) >>> 0
}
