import { PadRecordError } from './errors.js'

/**
 * Two inverted pad numbering conventions collide on this device:
 *
 * - Project-TAR filenames (`pads/{a,b,c,d}/pNN`) count bottom-up: `p01` is the
 *   bottom-left pad (".").
 * - SysEx `pad_num` (see `@kotu/ko2-protocol`'s `padFileId`) counts top-down:
 *   1 is the top-left pad ("7").
 *
 * This table is the full 12-entry mapping between the two, indexed by
 * `pad_num` (1-based). Ported from `references/knockout/core.js:80`
 * (`KO2_EXPORT_PAD_ORDER`), where `KO2_EXPORT_PAD_ORDER[padNum - 1]` gives the
 * tar suffix — verified against the real factory archive: `pads/c/p01`
 * (bottom-up) is SysEx `pad_num=10` (top-down), i.e. index 9 of this table is
 * `'p01'`.
 */
export const PAD_NUM_TO_TAR_NAME: readonly string[] = [
  'p10',
  'p11',
  'p12',
  'p07',
  'p08',
  'p09',
  'p04',
  'p05',
  'p06',
  'p01',
  'p02',
  'p03',
]

const TAR_NAME_TO_PAD_NUM: ReadonlyMap<string, number> = new Map(
  PAD_NUM_TO_TAR_NAME.map((name, index) => [name, index + 1]),
)

/** SysEx `pad_num` (1-12, top-down) for a project-TAR pad filename (`p01`..`p12`, bottom-up). */
export function tarNameToPadNum(tarName: string): number {
  const padNum = TAR_NAME_TO_PAD_NUM.get(tarName)
  if (padNum === undefined) throw new PadRecordError(`Not a pad filename: ${tarName}`)
  return padNum
}

/** Project-TAR pad filename (`p01`..`p12`, bottom-up) for a SysEx `pad_num` (1-12, top-down). */
export function padNumToTarName(padNum: number): string {
  const name = PAD_NUM_TO_TAR_NAME[padNum - 1]
  if (name === undefined) throw new PadRecordError(`pad_num out of range 1-12: ${padNum}`)
  return name
}
