import type { MidiTransport } from '@kotu/ko2-protocol'

export class NoWebMidiError extends Error {
  constructor() {
    super('This browser has no WebMIDI SysEx support. Use Chrome or Edge.')
    this.name = 'NoWebMidiError'
  }
}

export class NoDeviceError extends Error {
  constructor() {
    super('No EP device found. Connect an EP-133 / EP-40 (or sibling) over USB-C and reload.')
    this.name = 'NoDeviceError'
  }
}

export class MidiPermissionDeniedError extends Error {
  constructor(options?: { cause?: unknown }) {
    super(
      'MIDI access was denied. Click "Allow" on Chrome\'s MIDI permission prompt and reload the page.',
      options,
    )
    this.name = 'MidiPermissionDeniedError'
  }
}

export class AmbiguousDeviceError extends Error {
  constructor(kind: 'input' | 'output', count: number) {
    super(`Found ${count} EP ${kind} ports; expected exactly 1. Disconnect the extra device or stale virtual port.`)
    this.name = 'AmbiguousDeviceError'
  }
}

/**
 * TE EP-series USB MIDI product strings. Stock EP-133 is `EP-133`; after flashing
 * EP-40 firmware onto EP-133 hardware the ports rename to `EP-40`. Also matches
 * Medieval / EP-136 siblings that share the TE032 SysEx stack.
 */
export const EP_DEVICE_PORT_RE = /EP-(133|40|1320|136)\b/

/**
 * Binds `MidiTransport` to Chrome's WebMIDI. The only file in this codebase
 * that touches `navigator` — kept in its own package so `ko2-protocol` stays
 * environment-free.
 *
 * `send()` and `onmidimessage` carry the *complete* SysEx frame including
 * `F0`/`F7` in both directions; unlike `mido`, WebMIDI strips nothing. Bytes
 * are passed through untouched here — do not re-frame them.
 *
 * No throttling, chunking, or backpressure: measured on real hardware, 1083
 * chunk frames were accepted by `send()` in 28ms (they queue; transmission is
 * asynchronous) with zero dropped or reordered frames. Adding queueing here
 * would only slow the upload.
 */
export class WebMidiTransport implements MidiTransport {
  private handler: (bytes: Uint8Array) => void = () => {}

  // Stored so close() can verify it's still the installed listener before
  // nulling it out — a second transport attaching to the same port replaces
  // this, and this instance's close() must not clobber that replacement.
  private readonly midiMessageListener = (e: MIDIMessageEvent) => {
    if (e.data) this.handler(e.data)
  }

  constructor(
    private readonly input: MIDIInput,
    private readonly output: MIDIOutput,
  ) {
    if (input.onmidimessage != null) {
      throw new Error(
        'A WebMidiTransport is already attached to this MIDIInput. Close it before opening another.',
      )
    }
    input.onmidimessage = this.midiMessageListener
  }

  send(bytes: Uint8Array): void {
    // TypeScript's bundled lib.dom.d.ts types MIDIOutput.send as (data: number[])
    // even though the real WebMIDI spec and Chrome's actual implementation accept
    // a Uint8Array directly (this is a known gap in TS's ambient DOM types, not a
    // runtime restriction). Cast, don't convert: converting to a plain array would
    // allocate and copy on every send for no runtime benefit.
    this.output.send(bytes as unknown as number[])
  }

  onMessage(handler: (bytes: Uint8Array) => void): void {
    this.handler = handler
  }

  close(): void {
    // Only null the handler if it's still the one we installed — if another
    // transport has since attached to this port (replacing our listener),
    // nulling unconditionally would sever the live transport's messages.
    if (this.input.onmidimessage === this.midiMessageListener) {
      this.input.onmidimessage = null
    }
  }
}

/**
 * Requests SysEx access, finds an EP-series input/output pair, and wires them
 * into a `WebMidiTransport`. Port names are `EP-133` / `EP-40` / etc. on macOS;
 * see `EP_DEVICE_PORT_RE`.
 */
export async function openEp133(): Promise<WebMidiTransport> {
  const nav = globalThis.navigator as Navigator & {
    requestMIDIAccess?: typeof navigator.requestMIDIAccess
  }
  if (typeof nav?.requestMIDIAccess !== 'function') throw new NoWebMidiError()

  let midi: MIDIAccess
  try {
    midi = await nav.requestMIDIAccess({ sysex: true })
  } catch (err) {
    throw new MidiPermissionDeniedError({ cause: err })
  }

  const inputs: MIDIInput[] = []
  const outputs: MIDIOutput[] = []
  // MIDIInputMap/MIDIOutputMap only expose forEach in TS's ambient DOM types
  // (no .values()/.entries()/iterator), so iterate that way rather than casting.
  midi.inputs.forEach((p) => { if (EP_DEVICE_PORT_RE.test(p.name ?? '')) inputs.push(p) })
  midi.outputs.forEach((p) => { if (EP_DEVICE_PORT_RE.test(p.name ?? '')) outputs.push(p) })
  if (inputs.length > 1) throw new AmbiguousDeviceError('input', inputs.length)
  if (outputs.length > 1) throw new AmbiguousDeviceError('output', outputs.length)
  const input = inputs[0]
  const output = outputs[0]
  if (!input || !output) throw new NoDeviceError()

  return new WebMidiTransport(input, output)
}

/** A controller you can play the pads from. The EP device's own port is excluded: it is the target, not the source. */
export type ControllerPort = { id: string; name: string }

export type NoteEvent = { note: number; velocity: number }

/**
 * Every MIDI input except the connected EP device. Assumes SysEx access has already been
 * granted — `openEp133` does that — so this never prompts.
 */
export async function listControllers(): Promise<ControllerPort[]> {
  const nav = globalThis.navigator as Navigator & {
    requestMIDIAccess?: typeof navigator.requestMIDIAccess
  }
  if (typeof nav?.requestMIDIAccess !== 'function') throw new NoWebMidiError()
  const midi = await nav.requestMIDIAccess({ sysex: true })

  const ports: ControllerPort[] = []
  midi.inputs.forEach((p) => {
    if (!EP_DEVICE_PORT_RE.test(p.name ?? '')) ports.push({ id: p.id, name: p.name ?? p.id })
  })
  return ports
}

/**
 * Listen for note-on/note-off on one controller port. Returns an unsubscribe.
 *
 * A note-on with velocity 0 is a note-off; hardware has said so since 1983. SysEx and
 * clock traffic are ignored, so this can share a port with anything else.
 */
export async function onControllerNotes(
  portId: string,
  onNoteOn: (e: NoteEvent) => void,
  onNoteOff?: (e: NoteEvent) => void,
): Promise<() => void> {
  const nav = globalThis.navigator as Navigator & {
    requestMIDIAccess?: typeof navigator.requestMIDIAccess
  }
  if (typeof nav?.requestMIDIAccess !== 'function') throw new NoWebMidiError()
  const midi = await nav.requestMIDIAccess({ sysex: true })

  let port: MIDIInput | undefined
  midi.inputs.forEach((p) => { if (p.id === portId) port = p })
  if (!port) throw new NoDeviceError()

  const handler = (e: MIDIMessageEvent) => {
    const data = e.data
    if (!data || data.length < 3) return
    const status = data[0]! & 0xf0
    const note = data[1]!
    const velocity = data[2]!
    if (status === 0x90 && velocity > 0) onNoteOn({ note, velocity })
    else if (status === 0x80 || (status === 0x90 && velocity === 0)) onNoteOff?.({ note, velocity })
  }

  port.addEventListener('midimessage', handler as EventListener)
  const p = port
  return () => p.removeEventListener('midimessage', handler as EventListener)
}
