export const SYSEX_START = 0xf0
export const SYSEX_END = 0xf7
export const TE_MFG = [0x00, 0x20, 0x76] as const
/** Fixed TE SysEx marker after the per-device identity_code. */
export const MIDI_SYSEX_TE = 0x40
/** @deprecated Use DEFAULT_DEVICE_ID + MIDI_SYSEX_TE; identity_code is per-device. */
export const DEVICE_FAMILY = [0x33, MIDI_SYSEX_TE] as const
export const CMD_FILE = 0x05
export const SOUNDS_NODE = 1000
export const UPLOAD_CHUNK = 433

export type FileResponse = { cmd: number; seq: number; status: number; payload: Uint8Array }

export type SlotEntry = { slot: number; name: string; sizeBytes: number; isDir: boolean }

/** The 19 fields OS 2.5.1 returns for fileId = slot. */
export type SlotMeta = {
  channels: number
  samplerate: number
  format: 's16'
  crc: number
  name: string
  'sample.start': number
  'sample.end': number
  'sound.loopstart': number
  'sound.loopend': number
  'sound.amplitude': number
  'sound.pan': number
  'sound.pitch': number
  'sound.rootnote': number
  'sound.playmode': 'oneshot' | 'key' | 'legato'
  'sound.bpm': number
  'sound.bars': number
  'time.mode': 'off' | 'bar' | 'bpm' | 'reverse'
  'envelope.attack': number
  'envelope.release': number
}

/**
 * Built-in synth voice (EP-40 Supertone, etc.). These nodes have no PCM —
 * PLAYBACK on the voice id fails with "not found"; audition the assigned pad
 * file id instead (see `playbackFileIdForPad`).
 */
export type SynthMeta = {
  type: 'synth'
  name: string
}

export type NodeMeta = SlotMeta | SynthMeta

export function isSynthMeta(meta: unknown): meta is SynthMeta {
  return !!meta && typeof meta === 'object' && (meta as SynthMeta).type === 'synth'
}

export function isSlotMeta(meta: unknown): meta is SlotMeta {
  return !!meta && typeof meta === 'object' && typeof (meta as SlotMeta).channels === 'number'
}

/** The fields returned for a pad fileId. Sample pads and synth pads share most keys. */
export type PadMeta = {
  sym: number
  'sample.start': number
  'sample.end': number
  'sound.pitch': number
  'sound.playmode': 'oneshot' | 'key' | 'legato'
  'sound.amplitude': number
  'sound.pan': number
  'sound.mutegroup': boolean
  'envelope.attack': number
  'envelope.release': number
  'time.mode': 'off' | 'bar' | 'bpm' | 'reverse'
  'midi.channel': number
  /** Present on EP-40 pads; also sometimes echoed onto sample pads. */
  'sound.rootnote'?: number
  /** Encoder A/B values — presence marks a Supertone (or similar) synth assignment. */
  'synth.params'?: [number, number]
}

/** True when the pad points at a built-in synth voice rather than a sample slot. */
export function isSynthPad(pad: PadMeta): boolean {
  return Array.isArray(pad['synth.params'])
}

/**
 * pad_fid = 3200 + (project-1)*1000 + groupIndex*100 + padNum. groupIndex A=0..D=3, padNum 1..12.
 *
 * `padNum` is the SysEx `pad_num` convention: it counts top-down, 1 = the "7" key
 * (top-left of the pad grid). This is the INVERSE of the project-TAR `pNN`
 * filename convention, which counts bottom-up (`p01` = ".", bottom-left).
 * A caller iterating TAR filenames must invert `NN` before passing it here —
 * there is no conversion helper yet, so do this by hand.
 *
 * Worked example: `pads/c/p01` (bottom-up TAR numbering, group C) corresponds to
 * SysEx pad_num=10 (top-down), i.e. `padFileId(project, 2, 10)`.
 */
export function padFileId(project: number, groupIndex: number, padNum: number): number {
  return 3200 + (project - 1) * 1000 + groupIndex * 100 + padNum
}

/* ────────── From Teenage Engineering's own Sample Tool bundle ──────────
 * references/ep_133_sample_tool/data/index.js — class and constant names intact.
 * These supersede guesses made from packet captures.
 */

/** Sub-commands inside the FILE command group (byte 8 = 0x05). */
export const FILE_OP = {
  INIT: 1,
  PUT: 2,
  GET: 3,
  LIST: 4,
  PLAYBACK: 5,
  DELETE: 6,
  METADATA: 7,
  INFO: 11,   // we previously called this VERIFY; it is a stat
  MOVE: 12,
} as const

export const METADATA_OP = { SET: 1, GET: 2, SET_PAGED: 4 } as const
export const PAGED_TYPE = { INIT: 0, DATA: 1 } as const
export const PLAYBACK_ACTION = { START: 1, STOP: 2 } as const

/** `FILE_INIT` flags. The Sample Tool always subscribes — which is why the device
 *  pushes unsolicited event frames at us. */
export const FILE_INIT_SUBSCRIBE = 1

/** The `flags` byte on a directory entry is a capability mask, not just a type. */
export const FILE_FLAG = {
  FILE: 1, DIR: 2, READ: 4, WRITE: 8, DELETE: 16, MOVE: 32, PLAYBACK: 64,
} as const

export type FileCaps = {
  isFile: boolean; isDir: boolean
  canRead: boolean; canWrite: boolean; canDelete: boolean; canMove: boolean; canPlayback: boolean
}

export function decodeFlags(flags: number): FileCaps {
  return {
    isFile: !!(flags & FILE_FLAG.FILE),
    isDir: !!(flags & FILE_FLAG.DIR),
    canRead: !!(flags & FILE_FLAG.READ),
    canWrite: !!(flags & FILE_FLAG.WRITE),
    canDelete: !!(flags & FILE_FLAG.DELETE),
    canMove: !!(flags & FILE_FLAG.MOVE),
    canPlayback: !!(flags & FILE_FLAG.PLAYBACK),
  }
}

/** Unsolicited device events. Delivered on cmd 0x40 with NO status byte. */
export const FILE_EVENT = {
  METADATA_UPDATED: 3, FILE_ADDED: 8, FILE_UPDATED: 9, FILE_DELETED: 10, FILE_MOVED: 13,
} as const

export type FileEvent =
  | { type: 'file-added' | 'file-updated'; nodeId: number; fileSize: number; name: string }
  | { type: 'file-deleted'; nodeId: number }
  | { type: 'metadata-updated'; nodeId: number; metadata: Record<string, unknown> }
  | { type: 'file-moved'; nodeId: number }

/** A stat, from `SysexFileInfoResponse`. */
export type FileInfo = {
  nodeId: number; parentId: number; flags: number; fileSize: number; fileName: string
}
