import { pack7, unpack7 } from './packed7.js'
import { CMD_FILE, MIDI_SYSEX_TE, SYSEX_END, SYSEX_START, TE_MFG, type FileResponse } from './types.js'

/** Default identity_code observed on stock EP-133 units. EP-40 firmware uses 0x3c. */
export const DEFAULT_DEVICE_ID = 0x33

/** F0 | 00 20 76 | deviceId 40 | cmd | seq | 05 | packed7(payload) | F7 */
export function encodeFileFrame(
  cmd: number,
  seq: number,
  payload: number[],
  deviceId: number = DEFAULT_DEVICE_ID,
): Uint8Array {
  const packed = pack7(Uint8Array.from(payload))
  const out = new Uint8Array(9 + packed.length + 1)
  out[0] = SYSEX_START
  out.set(TE_MFG, 1)
  out[4] = deviceId
  out[5] = MIDI_SYSEX_TE
  out[6] = cmd
  out[7] = seq
  out[8] = CMD_FILE
  out.set(packed, 9)
  out[out.length - 1] = SYSEX_END
  return out
}

/** A non-FILE frame: used only by the two INIT messages, which carry a raw payload. */
export function encodeRawFrame(
  cmd: number,
  seq: number,
  payload: number[],
  deviceId: number = DEFAULT_DEVICE_ID,
): Uint8Array {
  // Unlike encodeFileFrame, the payload here is written unpacked (not run through
  // pack7), so every byte strictly between F0 and F7 must be <= 0x7f or the SysEx
  // message is corrupt.
  if (cmd > 0x7f) throw new Error(`encodeRawFrame: cmd 0x${cmd.toString(16)} has the high bit set (must be <= 0x7f)`)
  if (seq > 0x7f) throw new Error(`encodeRawFrame: seq 0x${seq.toString(16)} has the high bit set (must be <= 0x7f)`)
  if (deviceId > 0x7f) throw new Error(`encodeRawFrame: deviceId 0x${deviceId.toString(16)} has the high bit set (must be <= 0x7f)`)
  for (const b of payload) {
    if (b > 0x7f) throw new Error(`encodeRawFrame: payload byte 0x${b.toString(16)} has the high bit set (must be <= 0x7f)`)
  }
  return Uint8Array.from([SYSEX_START, ...TE_MFG, deviceId, MIDI_SYSEX_TE, cmd, seq, ...payload, SYSEX_END])
}

/**
 * TE teenage-mfg SysEx (not Universal Identity). Byte 4 is the device's
 * identity_code — 0x33 on stock EP-133, 0x3c under EP-40 firmware — so we only
 * require TE mfg + the fixed 0x40 marker.
 */
export function isTeFrame(raw: Uint8Array): boolean {
  return (
    raw.length >= 8 &&
    raw[0] === SYSEX_START &&
    raw[1] === TE_MFG[0] && raw[2] === TE_MFG[1] && raw[3] === TE_MFG[2] &&
    raw[5] === MIDI_SYSEX_TE
  )
}

/**
 * Byte 2 of a Universal Device Inquiry reply is the device_id TE uses in every
 * subsequent SysEx (identity_code). Returns null if the frame isn't a TE identity reply.
 */
export function parseIdentityDeviceId(raw: Uint8Array): number | null {
  // F0 7E <id> 06 02 00 20 76 …
  if (
    raw.length >= 8 &&
    raw[0] === SYSEX_START &&
    raw[1] === 0x7e &&
    raw[3] === 0x06 &&
    raw[4] === 0x02 &&
    raw[5] === TE_MFG[0] && raw[6] === TE_MFG[1] && raw[7] === TE_MFG[2]
  ) {
    return raw[2]!
  }
  return null
}

/**
 * cmd 0x40 with seq 0x00 is an unsolicited device push announcing a front-panel
 * change (e.g. {"sym":53}). It is never a reply. Never await respCmd === 0x40.
 */
export const PUSH_CMD = 0x40
export function isUnsolicitedPush(raw: Uint8Array): boolean {
  return isTeFrame(raw) && raw[6] === PUSH_CMD
}

/** FILE responses only. Status byte at index 9; packed payload from index 10. */
export function decodeResponse(raw: Uint8Array): FileResponse | null {
  if (!isTeFrame(raw) || raw.at(-1) !== SYSEX_END) return null
  // isUnsolicitedPush MUST be checked before the CMD_FILE guard below. Real device
  // pushes pack an arbitrary JSON payload after their header, and the byte that
  // lands at index 8 (where CMD_FILE would be) can coincidentally equal CMD_FILE
  // (0x05) — e.g. the real capture frame
  // F00020763340400005000325227B227379006D223A35337DF7 has raw[6] === 0x40 (a push)
  // and raw[8] === 0x05 purely by coincidence of its packed payload. If the
  // CMD_FILE guard ran first, this push would be misdecoded as a valid FILE
  // response. Reordering these two checks would silently do that.
  if (isUnsolicitedPush(raw)) return null
  if (raw[8] !== CMD_FILE) return null   // e.g. an INIT response, group 0x01
  // A well-formed FILE response needs F0 + 5 header bytes + cmd + seq + group +
  // status + F7 = 11 bytes minimum. Without this guard a 10-byte frame would have
  // its F7 terminator misread as the status byte at raw[9].
  if (raw.length < 11) return null
  return {
    cmd: raw[6]!,
    seq: raw[7]!,
    status: raw[9]!,
    payload: unpack7(raw.subarray(10, raw.length - 1)),
  }
}

export type DeviceInfo = { product: string; osVersion: string; serial: string; sku: string }

/** INIT responses use group byte 0x01, but the payload still starts at index 10. */
export function parseDeviceInfo(raw: Uint8Array): DeviceInfo {
  const text = new TextDecoder().decode(unpack7(raw.subarray(10, raw.length - 1)))
  const get = (k: string) => new RegExp(`(?:^|;)${k}:([^;]*)`).exec(text)?.[1] ?? ''
  return { product: get('product'), osVersion: get('os_version'), serial: get('serial'), sku: get('sku') }
}
