import type { Ep133Session } from '../session.js'
import { SOUNDS_NODE } from '../types.js'
import { getNodeMetadata } from './metadata.js'

/** What the `/sounds` directory node reports about the device's flash. */
export type Storage = {
  /** Total sample memory, in bytes. */
  maxCapacity: number
  /** Bytes still free. The device maintains this; do not compute it from slot sizes. */
  freeSpace: number
  /** Formats the device will accept on upload. */
  formats: unknown
}

type SoundsNodeMeta = {
  max_capacity: number
  free_space_in_bytes: number
  formats?: unknown
}

/**
 * Ask the device how big it is.
 *
 * The EP-133 ships as a 64 MB and a 128 MB unit, and **the SKU is identical for both**
 * (`TE032AS001`). Capacity cannot be inferred from the handshake, the model name, or the
 * manual — it has to be read. TE's own Sample Tool does exactly this:
 * `getMetadata("/sounds") → { free_space_in_bytes, max_capacity }`.
 *
 * A 64 MB unit reports `max_capacity = 62,853,120`.
 */
export async function getStorage(session: Ep133Session): Promise<Storage> {
  const meta = await getNodeMetadata<SoundsNodeMeta>(session, SOUNDS_NODE)
  return {
    maxCapacity: meta.max_capacity,
    freeSpace: meta.free_space_in_bytes,
    formats: meta.formats,
  }
}

/** The device pushes a metadata-updated event for this node when free space changes. */
export function isStorageNode(nodeId: number): boolean {
  return nodeId === SOUNDS_NODE
}
