import { Ep133Error, type Ep133Session } from '../session.js'
import { readBe16, readBe32, be16 } from '../wire.js'
import { SOUNDS_NODE, type SlotEntry } from '../types.js'

/**
 * The device has 999 slots and observed ~21 entries/page (35 pages observed on a
 * real unit); ~48 pages is the realistic worst case. 128 leaves ample headroom
 * while still catching a runaway/non-terminating LIST sequence instead of
 * silently truncating the result.
 */
export const MAX_LIST_PAGES = 128

export function parseListPage(payload: Uint8Array): SlotEntry[] {
  const out: SlotEntry[] = []
  let i = 2 // skip the 2-byte page header
  while (i + 7 <= payload.length) {
    const node = readBe16(payload, i); i += 2
    const flags = payload[i]!; i += 1
    const sizeBytes = readBe32(payload, i); i += 4
    let end = i
    while (end < payload.length && payload[end] !== 0x00) end++
    if (end >= payload.length) {
      throw new Ep133Error(`parseListPage: name terminator not found before end of payload (byte offset ${i})`)
    }
    const name = new TextDecoder().decode(payload.subarray(i, end))
    i = end + 1
    out.push({ slot: node, name, sizeBytes, isDir: !!(flags & 0x02) })
  }
  return out
}

export async function listSlots(session: Ep133Session): Promise<SlotEntry[]> {
  const all: SlotEntry[] = []
  let terminated = false
  for (let page = 0; page < MAX_LIST_PAGES; page++) {
    const res = await session.request(0x6a, [0x04, ...be16(page), ...be16(SOUNDS_NODE)], 0x2a)
    const entries = parseListPage(res.payload)
    if (entries.length === 0) {
      terminated = true
      break
    }
    all.push(...entries)
  }
  if (!terminated) {
    throw new Ep133Error(
      `listSlots: LIST did not terminate within ${MAX_LIST_PAGES} pages; result would be truncated`,
    )
  }
  const out: SlotEntry[] = []
  for (const e of all) {
    if (e.isDir || e.slot === SOUNDS_NODE) continue // expected: directories and the /sounds node itself
    if (e.slot < 1 || e.slot > 999) {
      throw new Ep133Error(`listSlots: entry with node id ${e.slot} outside the 1..999 slot range`)
    }
    out.push(e)
  }
  return out
}
