export const be16 = (v: number): number[] => [(v >> 8) & 0xff, v & 0xff]
export const be32 = (v: number): number[] => [
  (v >>> 24) & 0xff, (v >>> 16) & 0xff, (v >>> 8) & 0xff, v & 0xff,
]
/** 14-bit, LOW 7 bits first. Used only for download page numbers. */
export const u14le = (v: number): number[] => [v & 0x7f, (v >> 7) & 0x7f]

export const readBe16 = (d: Uint8Array, at: number): number => (d[at]! << 8) | d[at + 1]!
// Only the first term needs `>>> 0`: it's the only shift that can push an Int32
// negative (bit 31 set). The four terms must be combined with `+`, not `|` —
// wrapping all four in `>>> 0` and switching to `|` would reintroduce that bug.
export const readBe32 = (d: Uint8Array, at: number): number =>
  ((d[at]! << 24) >>> 0) + (d[at + 1]! << 16) + (d[at + 2]! << 8) + d[at + 3]!
export const readU14le = (d: Uint8Array, at: number): number => d[at]! | (d[at + 1]! << 7)
