import { utf8Decode, utf8Encode } from './bytes.js'
import { PakFormatError } from './errors.js'
import { readTar, writeTar } from './tar.js'
import type { TarEntry } from './tar.js'
import { readZip, writeZip } from './zip.js'
import type { ZipEntry } from './zip.js'

/** A project's decoded TAR entries — `pads`, `pads/{a,b,c,d}`, 48 pad files, `patterns`. */
export type ProjectTar = TarEntry[]

/**
 * `meta.json`, verbatim. `pak_type` has a third value beyond the `"project"`/`"user"` community
 * docs describe: a factory pak's is `"factory"` (verified against TE's own shipped archive — see
 * test/fixtures/factory-meta.json). `generated_at` is a human date string ("Nov 24, 2023"), not
 * ISO-8601 with milliseconds as `references/ep133-ppak/PROTOCOL.md` §9.2 claims — this module
 * makes no attempt to generate one; callers supply `meta` verbatim.
 */
export interface PakMeta {
  info: string
  pak_version: number
  pak_type: 'factory' | 'project' | 'user'
  pak_release: string
  device_name: string
  device_sku: string
  device_version: string
  generated_at: string
  author: string
  base_sku?: string
}

export interface PakSound {
  /** Basename as it appears under `/sounds/`, e.g. `"001 micro kick.wav"`. */
  name: string
  /** Raw WAV file bytes. Call `parseWav` from `./wav.js` to decode. */
  wav: Uint8Array
}

export interface Pak {
  meta: PakMeta
  /** Keyed by project name without extension, e.g. `"P01"`. */
  projects: Map<string, ProjectTar>
  /** Keyed by sound slot number, parsed from the `NNN ` filename prefix. */
  sounds: Map<number, PakSound>
  /**
   * Per-slot device metadata, keyed by slot. Absent in archives TE wrote — a `.pak` has
   * nowhere standard to record a slot's root note or amplitude, so kotu writes a sidecar.
   */
  slotMeta?: Map<number, Record<string, unknown>>
}

export interface Ppak {
  meta: PakMeta
  /** Project name without extension, e.g. `"P01"`. */
  projectName: string
  project: ProjectTar
  sounds: Map<number, PakSound>
}

const PROJECT_PATH_PATTERN = /^\/?projects\/([^/]+)\.tar$/
const SOUND_PATH_PATTERN = /^\/?sounds\/(.+)$/
const META_PATH_PATTERN = /^\/?meta\.json$/

/**
 * Per-slot device metadata — root note, amplitude, playmode — which TE's `.pak` has
 * nowhere to put. It lives in a sidecar TE's own tool ignores, so a kotu backup restores
 * a slot's edits and a TE backup still opens here (with no sidecar, and no edits).
 */
const SLOT_META_PATH = 'kotu/slot-metadata.json'
const SLOT_META_PATTERN = /^\/?kotu\/slot-metadata\.json$/
const SOUND_SLOT_PATTERN = /^(\d+)\s/

function archivePath(path: string): string {
  return path.startsWith('/') ? path : `/${path}`
}

/**
 * A project TAR must never carry a `settings` entry: a device that reads one raises
 * `ERROR CLOCK 43`, which survives a power cycle and requires a full flash format to clear — the
 * only known way to brick the device. `writePak`/`writePpak` check for it on every project so
 * that path is structurally unreachable through this module's write API.
 */
function assertNoSettingsEntry(projectName: string, project: ProjectTar): void {
  const hasSettings = project.some((entry) => entry.path === 'settings' || entry.path === '/settings')
  if (hasSettings) {
    throw new PakFormatError(
      `Project "${projectName}" has a "settings" entry — writing it would raise ERROR CLOCK 43 on the device, which survives a power cycle and requires a flash format to clear.`,
    )
  }
}

function parseMeta(bytes: Uint8Array): PakMeta {
  return JSON.parse(utf8Decode(bytes)) as PakMeta
}

function encodeMeta(meta: PakMeta): Uint8Array {
  return utf8Encode(`${JSON.stringify(meta, null, 2)}\n`)
}

function soundSlot(basename: string): number | null {
  const match = basename.match(SOUND_SLOT_PATTERN)
  return match ? Number(match[1]) : null
}

interface ParsedArchive {
  meta: PakMeta | undefined
  projects: Map<string, ProjectTar>
  sounds: Map<number, PakSound>
  slotMeta: Map<number, Record<string, unknown>> | undefined
}

function classifyEntries(zipEntries: Map<string, Uint8Array>): ParsedArchive {
  let meta: PakMeta | undefined
  let slotMeta: Map<number, Record<string, unknown>> | undefined
  const projects = new Map<string, ProjectTar>()
  const sounds = new Map<number, PakSound>()

  for (const [path, data] of zipEntries) {
    if (META_PATH_PATTERN.test(path)) {
      meta = parseMeta(data)
      continue
    }
    if (SLOT_META_PATTERN.test(path)) {
      slotMeta = parseSlotMeta(data)
      continue
    }
    const projectMatch = path.match(PROJECT_PATH_PATTERN)
    if (projectMatch) {
      projects.set(projectMatch[1]!, readTar(data))
      continue
    }
    const soundMatch = path.match(SOUND_PATH_PATTERN)
    if (soundMatch) {
      const name = soundMatch[1]!
      const slot = soundSlot(name)
      if (slot !== null) sounds.set(slot, { name, wav: data })
    }
  }
  return { meta, projects, sounds, slotMeta }
}

function parseSlotMeta(data: Uint8Array): Map<number, Record<string, unknown>> {
  let parsed: unknown
  try {
    parsed = JSON.parse(new TextDecoder().decode(data))
  } catch (err) {
    throw new PakFormatError(`${SLOT_META_PATH} is not valid JSON: ${(err as Error).message}`)
  }
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new PakFormatError(`${SLOT_META_PATH} must be an object keyed by slot number`)
  }
  const out = new Map<number, Record<string, unknown>>()
  for (const [key, value] of Object.entries(parsed as Record<string, unknown>)) {
    const slot = Number(key)
    if (!Number.isInteger(slot)) throw new PakFormatError(`${SLOT_META_PATH} has a non-numeric slot key: ${key}`)
    if (value === null || typeof value !== 'object' || Array.isArray(value)) {
      throw new PakFormatError(`${SLOT_META_PATH} entry for slot ${slot} is not an object`)
    }
    out.set(slot, value as Record<string, unknown>)
  }
  return out
}

function encodeSlotMeta(slotMeta: Map<number, Record<string, unknown>>): Uint8Array {
  const obj: Record<string, unknown> = {}
  for (const [slot, meta] of [...slotMeta].sort((a, b) => a[0] - b[0])) obj[String(slot)] = meta
  return new TextEncoder().encode(JSON.stringify(obj, null, 2))
}

/** Reads a `.pak` (multi-project) archive. */
export async function readPak(bytes: Uint8Array): Promise<Pak> {
  const zipEntries = await readZip(bytes)
  const { meta, projects, sounds, slotMeta } = classifyEntries(zipEntries)
  if (!meta) throw new PakFormatError('pak archive is missing meta.json')
  return { meta, projects, sounds, ...(slotMeta ? { slotMeta } : {}) }
}

/** Writes a `.pak` (multi-project) archive. Throws if any project would carry a `settings` entry. */
export async function writePak(pak: Pak): Promise<Uint8Array> {
  const entries: ZipEntry[] = []
  for (const [name, project] of pak.projects) {
    assertNoSettingsEntry(name, project)
    entries.push({ path: `/projects/${name}.tar`, data: writeTar(project) })
  }
  for (const sound of pak.sounds.values()) {
    entries.push({ path: archivePath(`sounds/${sound.name}`), data: sound.wav })
  }
  if (pak.slotMeta?.size) {
    entries.push({ path: archivePath(SLOT_META_PATH), data: encodeSlotMeta(pak.slotMeta) })
  }
  entries.push({ path: '/meta.json', data: encodeMeta(pak.meta) })
  return writeZip(entries)
}

/** Reads a `.ppak` (single-project) archive. */
export async function readPpak(bytes: Uint8Array): Promise<Ppak> {
  const zipEntries = await readZip(bytes)
  const { meta, projects, sounds } = classifyEntries(zipEntries)
  if (!meta) throw new PakFormatError('ppak archive is missing meta.json')
  const [[projectName, project] = [undefined, undefined]] = projects
  if (!projectName || !project) throw new PakFormatError('ppak archive is missing its project tar')
  return { meta, projectName, project, sounds }
}

/** Writes a `.ppak` (single-project) archive. Throws if the project would carry a `settings` entry. */
export async function writePpak(ppak: Ppak): Promise<Uint8Array> {
  assertNoSettingsEntry(ppak.projectName, ppak.project)
  const entries: ZipEntry[] = [{ path: `/projects/${ppak.projectName}.tar`, data: writeTar(ppak.project) }]
  for (const sound of ppak.sounds.values()) {
    entries.push({ path: archivePath(`sounds/${sound.name}`), data: sound.wav })
  }
  entries.push({ path: '/meta.json', data: encodeMeta(ppak.meta) })
  return writeZip(entries)
}
