import { isTeFrame, isUnsolicitedPush } from './frame.js'
import { unpack7 } from './packed7.js'
import { CMD_FILE, FILE_EVENT, type FileEvent } from './types.js'
import { readBe16, readBe32 } from './wire.js'

/**
 * Unsolicited device events.
 *
 * The Sample Tool's `FILE_INIT` request sets `flags = SUBSCRIBE`, and our handshake sends
 * the identical bytes — so the device streams events at us whether we listen or not. An
 * upload emits ~108 of them.
 *
 * The critical structural difference from a response: **an event frame carries no status
 * byte.** Its packed7 payload starts at index 9, not 10. Decoding it at 10 yields plausible
 * garbage, which is exactly what we got before reading TE's client.
 *
 * Payload: `[eventType:u8, ...body]`, per `onFileEvent` in index.js.
 */
export function decodeEvent(raw: Uint8Array): FileEvent | null {
  if (!isTeFrame(raw) || !isUnsolicitedPush(raw)) return null
  if (raw[8] !== CMD_FILE) return null

  const payload = unpack7(raw.subarray(9, raw.length - 1))
  if (payload.length < 1) return null

  const kind = payload[0]!
  const body = payload.subarray(1)
  const nodeId = body.length >= 2 ? readBe16(body, 0) : -1

  switch (kind) {
    case FILE_EVENT.FILE_ADDED:
    case FILE_EVENT.FILE_UPDATED: {
      // nodeId:u16, (2 reserved), fileSize:u32, name\0
      let end = 8
      while (end < body.length && body[end] !== 0x00) end++
      return {
        type: kind === FILE_EVENT.FILE_ADDED ? 'file-added' : 'file-updated',
        nodeId,
        fileSize: body.length >= 8 ? readBe32(body, 4) : 0,
        name: new TextDecoder().decode(body.subarray(8, end)),
      }
    }
    case FILE_EVENT.FILE_DELETED:
      return { type: 'file-deleted', nodeId }

    case FILE_EVENT.FILE_MOVED:
      return { type: 'file-moved', nodeId }

    case FILE_EVENT.METADATA_UPDATED: {
      // nodeId:u16, then a null-terminated JSON document
      let end = 2
      while (end < body.length && body[end] !== 0x00) end++
      const text = new TextDecoder().decode(body.subarray(2, end))
      try {
        return { type: 'metadata-updated', nodeId, metadata: JSON.parse(text) as Record<string, unknown> }
      } catch {
        return null
      }
    }
    default:
      return null
  }
}
