export function encodeWav(pcm: Uint8Array, opts: { channels: number; sampleRate: number }): Uint8Array<ArrayBuffer> {
  const { channels, sampleRate } = opts
  const byteRate = sampleRate * channels * 2
  const out = new Uint8Array(44 + pcm.length)
  const dv = new DataView(out.buffer)
  const ascii = (s: string, at: number) => { for (let i = 0; i < s.length; i++) out[at + i] = s.charCodeAt(i) }

  ascii('RIFF', 0); dv.setUint32(4, 36 + pcm.length, true); ascii('WAVE', 8)
  ascii('fmt ', 12); dv.setUint32(16, 16, true); dv.setUint16(20, 1, true)
  dv.setUint16(22, channels, true); dv.setUint32(24, sampleRate, true)
  dv.setUint32(28, byteRate, true); dv.setUint16(32, channels * 2, true); dv.setUint16(34, 16, true)
  ascii('data', 36); dv.setUint32(40, pcm.length, true)
  out.set(pcm, 44)
  return out
}

export function decodeWav(wav: Uint8Array): { pcm: Uint8Array; channels: number; sampleRate: number } {
  const dv = new DataView(wav.buffer, wav.byteOffset, wav.byteLength)
  const tag = (at: number) => String.fromCharCode(wav[at]!, wav[at + 1]!, wav[at + 2]!, wav[at + 3]!)
  if (wav.length < 44 || tag(0) !== 'RIFF' || tag(8) !== 'WAVE') throw new Error('not a RIFF/WAVE file')

  let channels = 1, sampleRate = 46875
  let i = 12
  while (i + 8 <= wav.length) {
    const id = tag(i)
    const size = dv.getUint32(i + 4, true)
    if (id === 'fmt ') { channels = dv.getUint16(i + 10, true); sampleRate = dv.getUint32(i + 12, true) }
    if (id === 'data') return { pcm: wav.subarray(i + 8, i + 8 + size), channels, sampleRate }
    i += 8 + size + (size & 1)
  }
  throw new Error('no data chunk')
}
