import { Ep133Error, type Ep133Session } from '../session.js'
import { be16, readBe16 } from '../wire.js'

/**
 * Observed worst case is 2 pages for a real slot's metadata. 64 leaves ample
 * headroom while still catching a runaway/non-terminating READ sequence
 * instead of silently spinning or truncating the result.
 */
const MAX_METADATA_PAGES = 64

function stripTrailingNul(text: string): string {
  return text.replace(/\0+$/, '')
}

/** Like JSON.parse, but returns undefined instead of throwing on invalid input. */
function tryParseJson(text: string): unknown | undefined {
  try {
    return JSON.parse(text)
  } catch {
    return undefined
  }
}

/** The device stalls past 320 bytes of JSON, returning a truncated blob. Recover what we can. */
export function parseTolerantJson(text: string): unknown {
  const clean = stripTrailingNul(text)
  const whole = tryParseJson(clean)
  if (whole !== undefined) return whole
  const closed = tryParseJson(clean + '}')
  if (closed !== undefined) return closed
  const cut = clean.lastIndexOf(',')
  if (cut > 0) {
    const trimmed = tryParseJson(clean.slice(0, cut) + '}')
    if (trimmed !== undefined) return trimmed
  }
  throw new Ep133Error(`unparseable metadata JSON: ${clean.slice(0, 80)}`)
}

export async function getNodeMetadata<T>(session: Ep133Session, nodeId: number): Promise<T> {
  let text = ''
  let terminated = false
  for (let page = 0; page < MAX_METADATA_PAGES; page++) {
    // Only the first page's status is ambiguous on hardware: an empty slot answers
    // status=0x01 with an ASCII reason instead of a page echo + JSON, so that one
    // request must opt out of the default status check to read the reason at all.
    // Every subsequent page (page > 0) only happens once page 0 proved the slot
    // exists, so the default check is safe and desired there.
    const res =
      page === 0
        ? await session.request(0x6a, [0x07, 0x02, ...be16(nodeId), ...be16(page)], 0x2a, 2000, { checkStatus: false })
        : await session.request(0x6a, [0x07, 0x02, ...be16(nodeId), ...be16(page)], 0x2a)

    if (page === 0 && res.status !== 0) {
      const reason = new TextDecoder().decode(res.payload).replace(/\0+$/, '')
      throw new Ep133Error(`node ${nodeId} has no metadata: ${reason}`, res.status)
    }

    // The device echoes the requested page in the first two payload bytes. Verify it:
    // a name like "a}b" would make the accumulated text contain a stray '}' that used
    // to be (mis)treated as a stop condition, so we can no longer trust brace-counting
    // to detect a desynced page request either — the echo check is the real guard.
    // Only valid on the status===0 path — the error payload above is NOT an echo + JSON.
    const echo = readBe16(res.payload, 0)
    if (echo !== page) {
      throw new Ep133Error(`metadata page echo mismatch for node ${nodeId}: requested ${page}, device returned ${echo}`)
    }

    const chunk = res.payload.subarray(2)
    if (chunk.length === 0) {
      // Device has no more data. This is the legitimate "object ended early" case —
      // tolerant recovery on what we have so far is the right move, not an error.
      terminated = true
      break
    }
    text += new TextDecoder().decode(chunk)

    // Stop when the accumulated text actually parses as JSON, not when it merely
    // contains a '}' — a `name` field can itself contain a closing brace.
    const parsed = tryParseJson(stripTrailingNul(text))
    if (parsed !== undefined) return parsed as T
  }

  if (!terminated) {
    throw new Ep133Error(
      `getNodeMetadata: node ${nodeId} metadata did not terminate within ${MAX_METADATA_PAGES} pages; result would be truncated`,
    )
  }

  return parseTolerantJson(text) as T
}

/**
 * Cheap existence probe: one round trip.
 * Measured on hardware: an occupied slot answers status=0x00 with a page echo + JSON;
 * an EMPTY slot answers status=0x01 with the ASCII reason 'invalid file id'.
 */
export async function slotExists(session: Ep133Session, slot: number): Promise<boolean> {
  const res = await session.request(0x6a, [0x07, 0x02, ...be16(slot), ...be16(0)], 0x2a, 2000, {
    checkStatus: false,
  })
  if (res.status !== 0) return false
  return res.payload.length > 2
}

export async function setNodeMetadata(
  session: Ep133Session,
  nodeId: number,
  patch: Record<string, unknown>,
): Promise<void> {
  const json = [...new TextEncoder().encode(JSON.stringify(patch))]
  // 320 is the *observed read* page size; the write limit is unverified on real
  // hardware. Guard conservatively at the same figure anyway — our real writes are
  // ~200 bytes, so nothing legitimate should ever hit this.
  if (json.length > 320) {
    throw new Ep133Error(`setNodeMetadata: patch is ${json.length} bytes, exceeds the 320-byte device page limit`)
  }
  await session.request(0x6a, [0x07, 0x01, ...be16(nodeId), ...json], 0x2a)
}
