import { concatBytes, utf8Decode, utf8Encode } from './bytes.js'
import { TarFormatError } from './errors.js'

const HEADER_SIZE = 512
const TERMINATOR_SIZE = 1024
const NAME_FIELD_LEN = 100
const SIZE_FIELD_OFFSET = 124
const SIZE_FIELD_LEN = 12
const CHECKSUM_FIELD_OFFSET = 148
const CHECKSUM_FIELD_LEN = 8
const TYPEFLAG_OFFSET = 156
const TYPEFLAG_FILE = 0x30 // '0'
const TYPEFLAG_DIRECTORY = 0x35 // '5'

export interface TarEntry {
  path: string
  type: 'file' | 'directory'
  /** Must be empty for `type: 'directory'`. */
  data: Uint8Array
}

/**
 * The EP-133's project-TAR headers are NOT ustar/POSIX tar, despite every
 * community doc (and the original plan for this module) assuming they are.
 * Verified against `test/fixtures/P01.tar`, a real project TAR extracted
 * from TE's own factory `.pak`, across all 54 of its entries:
 *
 * - No `ustar\0` magic, no version, no uname/gname/devmajor/devminor/prefix.
 *   Those 208 bytes (257-465) are always zero.
 * - `mode`, `uid`, `gid` (offsets 100-124) are always all-zero — not the
 *   octal-text "0000755"/"0000644" a POSIX header would carry. This device's
 *   writer appears to skip numeric fields entirely when the value is 0,
 *   rather than writing a zero-padded octal string.
 * - `size` and `mtime` follow the same "skip when zero" rule; when nonzero
 *   (only `size`, in practice), the field holds the bare octal digits with
 *   no leading-zero padding, e.g. size 26 is the 2 bytes `"32"` (octal),
 *   left-anchored, with the rest of the 12-byte field zero — not the
 *   11-digit zero-padded octal string ustar would write.
 * - `chksum` is the one field that always has content (it's never 0): bare
 *   octal digits, then a single NUL, then the remainder of the 8-byte field
 *   filled with spaces (matching the POSIX checksum convention, just without
 *   the fixed 6-digit zero-padding). Verified to equal the standard tar
 *   checksum (sum of all header bytes with the checksum field itself treated
 *   as 8 spaces) for all 54 entries.
 * - The archive still ends with a 1024-byte (two 512-byte blocks) zero
 *   terminator, and pad-record files still use `mtime 0`, 512-byte blocks —
 *   those parts of the original plan were correct.
 *
 * `writeTar` reproduces this exact real-device encoding so that
 * `writeTar(readTar(P01.tar))` is byte-identical to the fixture. `readTar`
 * only depends on `path`/`size`/`typeflag`, so it also accepts standard
 * ustar tars (e.g. from other tools) — it just never emits their extra
 * fields back out.
 */
function computeChecksum(header: Uint8Array): number {
  let sum = 0
  for (let i = 0; i < HEADER_SIZE; i++) {
    sum += i >= CHECKSUM_FIELD_OFFSET && i < CHECKSUM_FIELD_OFFSET + CHECKSUM_FIELD_LEN ? 0x20 : header[i]!
  }
  return sum
}

function writeName(header: Uint8Array, path: string): void {
  const bytes = utf8Encode(path)
  if (bytes.byteLength > NAME_FIELD_LEN) {
    throw new TarFormatError(`tar entry name exceeds ${NAME_FIELD_LEN} bytes: ${path}`)
  }
  header.set(bytes, 0)
}

/** Real-device convention: a value of 0 leaves the field entirely zero (no digit at all). */
function writeOctalField(header: Uint8Array, offset: number, length: number, value: number): void {
  if (value === 0) return
  const digits = value.toString(8)
  if (digits.length > length) {
    throw new TarFormatError(`tar numeric field overflow at offset ${offset}: ${value}`)
  }
  header.set(utf8Encode(digits), offset)
}

/** The one field that's always present: bare octal digits, NUL, then space-fill. */
function writeChecksumField(header: Uint8Array): void {
  const value = computeChecksum(header)
  const digits = value.toString(8)
  if (digits.length + 1 > CHECKSUM_FIELD_LEN) {
    throw new TarFormatError(`tar checksum overflow: ${value}`)
  }
  header.set(utf8Encode(digits), CHECKSUM_FIELD_OFFSET)
  header[CHECKSUM_FIELD_OFFSET + digits.length] = 0
  header.fill(0x20, CHECKSUM_FIELD_OFFSET + digits.length + 1, CHECKSUM_FIELD_OFFSET + CHECKSUM_FIELD_LEN)
}

function buildHeader(entry: TarEntry): Uint8Array {
  const header = new Uint8Array(HEADER_SIZE)
  writeName(header, entry.path)
  writeOctalField(header, SIZE_FIELD_OFFSET, SIZE_FIELD_LEN, entry.type === 'directory' ? 0 : entry.data.byteLength)
  // mtime (offset 136, len 12) is always 0 on this device: left blank.
  header[TYPEFLAG_OFFSET] = entry.type === 'directory' ? TYPEFLAG_DIRECTORY : TYPEFLAG_FILE
  writeChecksumField(header)
  return header
}

/** Serializes tar entries to the EP-133's real (non-ustar) project-TAR byte format. */
export function writeTar(entries: TarEntry[]): Uint8Array {
  const parts: Uint8Array[] = []
  for (const entry of entries) {
    if (entry.type === 'directory' && entry.data.byteLength !== 0) {
      throw new TarFormatError(`directory entry must carry no data: ${entry.path}`)
    }
    parts.push(buildHeader(entry))
    if (entry.type === 'file') {
      parts.push(entry.data)
      const padLength = (HEADER_SIZE - (entry.data.byteLength % HEADER_SIZE)) % HEADER_SIZE
      if (padLength > 0) parts.push(new Uint8Array(padLength))
    }
  }
  parts.push(new Uint8Array(TERMINATOR_SIZE))
  return concatBytes(parts)
}

function readOctalField(header: Uint8Array, offset: number, length: number): number {
  const text = utf8Decode(header.subarray(offset, offset + length))
    .replace(/\0.*$/, '')
    .trim()
  return text ? parseInt(text, 8) : 0
}

/** Parses a tar archive. Reads structurally (path/size/typeflag); ignores ustar-only fields. */
export function readTar(bytes: Uint8Array): TarEntry[] {
  const entries: TarEntry[] = []
  let offset = 0
  while (offset + HEADER_SIZE <= bytes.byteLength) {
    const header = bytes.subarray(offset, offset + HEADER_SIZE)
    if (header.every((byte) => byte === 0)) break
    const path = utf8Decode(header.subarray(0, NAME_FIELD_LEN)).replace(/\0.*$/, '')
    const size = readOctalField(header, SIZE_FIELD_OFFSET, SIZE_FIELD_LEN)
    const type: TarEntry['type'] = header[TYPEFLAG_OFFSET] === TYPEFLAG_DIRECTORY ? 'directory' : 'file'
    const dataStart = offset + HEADER_SIZE
    const dataLength = type === 'directory' ? 0 : size
    const dataEnd = dataStart + dataLength
    if (dataEnd > bytes.byteLength) throw new TarFormatError(`Truncated tar entry: ${path}`)
    entries.push({ path, type, data: bytes.slice(dataStart, dataEnd) })
    const padLength = dataLength === 0 ? 0 : (HEADER_SIZE - (dataLength % HEADER_SIZE)) % HEADER_SIZE
    offset = dataEnd + padLength
  }
  return entries
}
