import { Ep133Error, type Ep133Session } from '../session.js'
import { be16, readBe32, readU14le, u14le } from '../wire.js'

const MAX_SIZE = 512 * 1024 * 1024

/**
 * The download page counter is 14-bit (u14le), addressing pages 0..0x3FFF
 * (16384 values). Measured on slot 1: ~322 B/chunk observed (44,824 bytes over
 * ~139 chunk responses), so the page space covers 16384 * 322 ≈ 5.36 MB, while
 * the largest possible sample (40s mono) is 3.75 MB — only a 1.4x margin.
 * Bounding the loop here makes that margin an explicit, checked invariant
 * instead of an incidental one; see MAX_DOWNLOAD_PAGES below.
 */
const MAX_DOWNLOAD_PAGES = 16384

export function extractDownloadSize(payload: Uint8Array): number {
  if (payload.length < 7) {
    throw new Ep133Error(`download-init payload too short to contain a size: ${payload.length} bytes (need at least 7)`)
  }
  const size = readBe32(payload, 3)
  if (!Number.isSafeInteger(size)) {
    throw new Ep133Error(`download-init size is not a safe integer: ${size}`)
  }
  if (size <= 0 || size >= MAX_SIZE) throw new Ep133Error(`implausible download size ${size}`)
  return size
}

export async function downloadSlot(
  session: Ep133Session,
  slot: number,
  onProgress?: (done: number, total: number) => void,
): Promise<Uint8Array> {
  const init = await session.request(0x7d, [0x03, 0x00, ...be16(slot), 0, 0, 0, 0, 0], 0x3d, 5000)

  // try/finally opens HERE, immediately after the download-init request returns —
  // not after extractDownloadSize(). The device is already in download mode by the
  // time init resolves, so an implausible/too-short size from extractDownloadSize()
  // must still trigger reinit() below; otherwise the device stays in download mode
  // and silently answers the next command with stale GET data.
  let pending: unknown
  try {
    const total = extractDownloadSize(init.payload)

    // Only reachable once extractDownloadSize() succeeds, at which point the session
    // is still 'ready' (nothing between the init request above and here can have
    // changed it) — enterTransfer()'s state precondition holds exactly as before.
    session.enterTransfer()

    const pcm = new Uint8Array(total)
    let got = 0
    let page = 0
    let consecutiveEmptyChunks = 0

    for (let iterations = 0; got < total; iterations++) {
      if (iterations >= MAX_DOWNLOAD_PAGES) {
        throw new Ep133Error(
          `downloadSlot: slot ${slot} did not terminate within ${MAX_DOWNLOAD_PAGES} chunk requests; result would be truncated (${got}/${total} bytes)`,
        )
      }
      if (page > 0x3fff) {
        throw new Ep133Error(
          `downloadSlot: slot ${slot} exceeds the addressable 14-bit page space (0x3FFF); ${got}/${total} bytes downloaded so far`,
        )
      }

      // checkStatus:false — download chunk responses do not carry a standard status byte.
      // krate's _recv_download_chunk validates cmd and file_cmd only (client.py:696-717).
      const res = await session.requestDuringTransfer(0x7d, [0x03, 0x01, ...u14le(page)], 0x3d, 2500, {
        checkStatus: false,
      })
      const echo = readU14le(res.payload, 0)
      if (echo !== page) {
        throw new Ep133Error(
          `downloadSlot: page echo mismatch for slot ${slot} at byte offset ${got}: requested page ${page}, device echoed ${echo}`,
        )
      }

      const data = res.payload.subarray(2)
      if (data.length === 0) {
        consecutiveEmptyChunks++
        if (consecutiveEmptyChunks >= 2) {
          throw new Ep133Error(
            `downloadSlot: slot ${slot} returned two consecutive empty chunks at page ${page} (${got}/${total} bytes); device is not making progress`,
          )
        }
      } else {
        consecutiveEmptyChunks = 0
      }

      if (data.length > total - got) {
        throw new Ep133Error(
          `downloadSlot: slot ${slot} over-served at page ${page}: chunk had ${data.length} bytes but only ${total - got} remained`,
        )
      }

      pcm.set(data, got)
      got += data.length
      page = page + 1
      onProgress?.(got, total)
    }
    return pcm
  } catch (err) {
    pending = err
    throw err
  } finally {
    // Mandatory: the device stays in download mode and drops the next command
    // otherwise. Must run on every exit path, including a throw above — an
    // interrupted download must not leave the device or session wedged. A
    // reinit() failure here must not mask an in-flight error from the chunk
    // loop; only surface it when the loop itself succeeded.
    try {
      await session.reinit()
    } catch (reinitErr) {
      if (pending === undefined) throw reinitErr
    }
  }
}
